int main(int argc, char **argv) {
    if (argc != 2) return 2;
    char *end;
    long pid = strtol(argv[1], &end, 10);
    if (*end || pid < 1 || pid > INT32_MAX) return 2;
    uint64_t threads[4096];
    int count = proc_pidinfo((int)pid, PROC_PIDLISTTHREADS, 0, threads, sizeof threads);
    if (count <= 0 || count == sizeof threads || count % sizeof threads[0]) {
        perror("PROC_PIDLISTTHREADS");
        return 1;
    }
    for (size_t i = 0; i < (size_t)count / sizeof threads[0]; ++i) {
        struct proc_threadinfo thread = {0};
        if (proc_pidinfo((int)pid, PROC_PIDTHREADID64INFO, threads[i], &thread, sizeof thread) == sizeof thread) {
