async function sample(binary) {
  const profile = await mkdtemp(join(scratch, 'fixture-'));
  const socket = createSocket('udp4');
  await new Promise((ok, reject) => {
    socket.once('error', reject);
    socket.bind(0, '127.0.0.1', ok);
