  const closed = once(node, 'close');
  const terminate = () => node.kill('SIGTERM');
  process.once('SIGINT', terminate);
  process.once('SIGTERM', terminate);
  let destination = '';
  node.stdout.setEncoding('utf8');
  node.stdout.on('data', chunk => { destination = (destination + chunk).slice(-4096); });
  node.stderr.resume();
  try {
    while (!/node \\S+ listening on tcp\\//.test(destination)) {
      assert.equal(node.exitCode, null, 'node retired before listening');
      assert(performance.now() - processStart < 60000, 'node startup deadline');
      await wait(200);
    }
    await wait(15000);
    const read = () => JSON.parse(execFileSync(sampler, [String(node.pid)], { encoding: 'utf8' }));
    const start = performance.now();
    const first = read();
    await wait(seconds * 1000);
    const last = read();
    const elapsed = (performance.now() - start) / 1000;
    assert.equal(first.start, last.start, 'node process identity');
    return { binary, seconds: elapsed, cpuPercentOneCore: 100 * (last.cpuSeconds - first.cpuSeconds) / elapsed,
      interruptWakeups: last.interruptWakeups - first.interruptWakeups,
      packageIdleWakeups: last.packageIdleWakeups - first.packageIdleWakeups,
      attributableWriteBytes: last.writeBytes - first.writeBytes };
  } finally {
    process.off('SIGINT', terminate);
    process.off('SIGTERM', terminate);
    if (node.exitCode === null && node.signalCode === null) {
      node.stdin.end('/quit\\n');
      let timer;
      try {
        await Promise.race([closed, new Promise(resolve => { timer = setTimeout(resolve, 5000); })]);
      } finally { clearTimeout(timer); }
      if (node.exitCode === null && node.signalCode === null) terminate();
    }
    await closed;
    await rm(profile, { recursive: true });
  }
}

