use std::{
    sync::{Arc, atomic::{AtomicBool, Ordering}},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tauri::{Listener, Manager, webview::PageLoadEvent};

fn phase(app: &tauri::AppHandle, name: &str, minimized: bool, interval: Duration) {
    let handle = app.clone();
    let (send, receive) = std::sync::mpsc::sync_channel(1);
    app.run_on_main_thread(move || {
        let window = handle.get_webview_window("main").unwrap();
        if minimized {
            window.minimize().unwrap();
        } else {
            window.show().unwrap();
            window.set_focus().unwrap();
        }
        send.send(()).unwrap();
    }).unwrap();
    receive.recv_timeout(Duration::from_secs(5)).unwrap();
    std::thread::sleep(Duration::from_secs(5));
    let handle = app.clone();
    let (send, receive) = std::sync::mpsc::sync_channel(1);
    app.run_on_main_thread(move || {
        let window = handle.get_webview_window("main").unwrap();
        send.send((window.is_minimized().unwrap(), window.is_focused().unwrap())).unwrap();
    }).unwrap();
    let (actual_minimized, focused) = receive.recv_timeout(Duration::from_secs(5)).unwrap();
    assert_eq!(actual_minimized, minimized);
    assert_eq!(focused, !minimized);
    marker(name, "start");
    std::thread::sleep(interval);
    marker(name, "end");
}

fn marker(phase: &str, boundary: &str) {
    eprintln!("MEASURE {phase} {boundary} {:.6}", SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs_f64());
}

fn main() {
    let mut args = std::env::args().skip(1);
    let root = std::path::PathBuf::from(args.next().expect("fixture root"));
    let port = args.next().expect("discovery port").parse().unwrap();
    let interval = Duration::from_secs(args.next().expect("sample seconds").parse().unwrap());
    assert!(args.next().is_none());
    assert!(root.is_absolute());
    assert!(!root.exists(), "require a fresh fixture root");
    std::fs::create_dir_all(&root).unwrap();
    mesh_talk::run_tauri_configured(Some(root), Some(port), |builder| {
