use serde::Deserialize;
use std::{
    fs,
    path::{Path, PathBuf},
};

type Error = Box<dyn std::error::Error>;

#[derive(Deserialize)]
struct Manifest {
    source: String,
    groups: Vec<[u8; 32]>,
    accounts: Vec<String>,
    dm_per_contact: usize,
    group_messages: usize,
    completed: bool,
}

fn copy_profile(source: &Path, destination: &Path) -> Result<(), Error> {
    fs::create_dir(&destination)?;
    for entry in fs::read_dir(source)? {
        let entry = entry?;
        let kind = entry.file_type()?;
        let name = entry.file_name();
        let target = destination.join(if name == "node.keystore" {
            std::ffi::OsStr::new("identity.keystore")
        } else {
            name.as_os_str()
        });
        if target.exists() {
            return Err("conflicting profile paths".into());
        }
        if kind.is_dir() {
            copy_profile(&entry.path(), &target)?;
        } else if kind.is_file() {
            fs::copy(entry.path(), target)?;
        } else {
            return Err("fixture profiles must contain only regular files and directories".into());
        }
    }
    Ok(())
}

fn main() -> Result<(), Error> {
    let mut args = std::env::args_os().skip(1);
    let source = PathBuf::from(args.next().ok_or("fixture directory required")?).canonicalize()?;
    let destination = PathBuf::from(args.next().ok_or("fresh desktop data root required")?);
    let password_file = PathBuf::from(args.next().ok_or("fixture password file required")?);
    if args.next().is_some() || !destination.is_absolute() {
        return Err("pass an absolute fresh desktop data root and no other arguments".into());
    }
    let manifest: Manifest = serde_json::from_slice(&fs::read(source.join("manifest.json"))?)?;
    if !manifest.completed || manifest.accounts.is_empty() || manifest.groups.is_empty() {
        return Err("complete and verify the source fixture before staging it".into());
    }
    let owner = source.join("owner");
    if !owner.join("node.keystore").is_file() || !owner.join("account.keystore").is_file() {
        return Err("source fixture is missing its runtime identities".into());
    }

    fs::create_dir(&destination)?;
    let password = fs::read_to_string(password_file)?;
    let password = password.trim();
    let manager = IdentityManager::new(FileManager::new(destination.clone()));
    let user = manager.register_user("reference-eval", password)?;
    let resolved = manager.authenticate_account_login(&user.username, password)?;
    if resolved.user.user_id != user.user_id || resolved.node_storage_password != password {
        return Err("desktop credentials do not resolve to the fixture storage secret".into());
    }

    let account_root = destination.join("accounts");
    fs::create_dir_all(&account_root)?;
    copy_profile(&owner, &account_root.join(&user.user_id))?;
    println!("{}", serde_json::json!({
        "owner": user.user_id,
        "username": user.username,
        "source": manifest.source,
        "contacts": manifest.accounts.len(),
        "groups": manifest.groups.len(),
        "messages": manifest.accounts.len() * manifest.dm_per_contact
            + manifest.groups.len() * manifest.group_messages
    }));
    Ok(())
}
