use mesh_talk_core::{eventlog::event::ConversationId, node::Node, recovery::key::RecoveryKey};
use std::{fs::{File, OpenOptions}, path::Path, time::{SystemTime, UNIX_EPOCH}};

#[derive(serde::Deserialize)]
struct Manifest {
    completed: bool,
    accounts: Vec<String>,
    groups: Vec<[u8; 32]>,
    dm_per_contact: usize,
    group_messages: usize,
}

fn verify(node: &Node, manifest: &Manifest) -> Result<(), Box<dyn std::error::Error>> {
    assert!(manifest.completed);
    assert_eq!(node.list_channels()?.len(), manifest.groups.len());
    for account in &manifest.accounts {
        assert_eq!(node.account_history(account, manifest.dm_per_contact + 1)?.len(), manifest.dm_per_contact);
    }
    for group in &manifest.groups {
        assert_eq!(node.channel_history(ConversationId::new(*group), manifest.group_messages + 1)?.len(), manifest.group_messages);
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    assert_eq!(args.len(), 7, "mode profile password key archive manifest scratch");
    let profile = Path::new(&args[1]);
    let password = std::fs::read_to_string(&args[2])?;
    let key = RecoveryKey::parse(&std::fs::read_to_string(&args[3])?)?;
    let manifest: Manifest = serde_json::from_reader(File::open(&args[5])?)?;
    match args[0].as_str() {
        "export" => {
            let node = Node::open_recovery_profile(profile, password.trim())?;
            verify(&node, &manifest)?;
            let archive = OpenOptions::new().create_new(true).write(true).open(&args[4])?;
            node.write_encrypted_recovery_archive(
                archive, &key, SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis() as u64,
            )?;
            node.close_profile()?;
        }
        "import" => {
            let (node, _) = Node::install_encrypted_recovery_archive(
                File::open(&args[4])?, &key, Path::new(&args[6]), profile, password.trim(),
            )?;
            verify(&node, &manifest)?;
            node.close_profile()?;
        }
        _ => return Err("unknown transfer operation".into()),
    }
    println!("{}: verified {} conversations and {} messages", args[0],
        manifest.accounts.len() + manifest.groups.len(),
        manifest.accounts.len() * manifest.dm_per_contact + manifest.groups.len() * manifest.group_messages);
    Ok(())
}
