text(await tools.exec_command({cmd:`cat > tmp/req-011/desktop-phase-summary.py <<'PY'
"""Analyze native desktop counters within fixture-marked phases."""
import json
import re
import sys
from pathlib import Path

MARKER = re.compile(r"^MEASURE (foreground|minimized) (start|end) (\\d+\\.\\d+)$", re.MULTILINE)
CPU_LIMITS = {"foreground": 1.0, "minimized": 0.25}


def summarize(log, observations, min_seconds=300, settle=15):
    markers = {}
    for phase, edge, value in MARKER.findall(log):
        key = phase, edge
        if key in markers:
            raise ValueError(f"duplicate marker {key}")
        markers[key] = float(value)
    summaries = {}
    for phase, cpu_limit in CPU_LIMITS.items():
        start, stop = (markers[phase, edge] for edge in ("start", "end"))
        window = [
            (row["at"] / 1000, row["members"])
            for row in observations["samples"]
            if start + settle <= row["at"] / 1000 < stop
        ]
        if len(window) < 2 or window[-1][0] - window[0][0] < min_seconds:
            raise ValueError(f"incomplete measurement window: {phase}")
        identity = lambda item: (item["pid"], item["start"], item["role"])
        first = {identity(item): item for item in window[0][1]}
        roles = {key[2] for key in first}
        if not {"host", "renderer"} <= roles:
            raise ValueError(f"desktop family is missing its host or renderer: {phase}")
        previous = first
        peak_private = peak_working_set = 0
        for _, members in window:
            samples = {identity(item): item for item in members}
            if samples.keys() != first.keys():
                raise ValueError(f"desktop family changed during {phase}")
            if any(samples[key]["cpuSeconds"] < previous[key]["cpuSeconds"] for key in samples):
                raise ValueError(f"CPU counter regressed during {phase}")
            previous = samples
            peak_private = max(peak_private, sum(item["privateBytes"] for item in members))
            peak_working_set = max(peak_working_set, sum(item["workingSetBytes"] for item in members))
        seconds = window[-1][0] - window[0][0]
        by_role = {
            role: 100 * sum(previous[key]["cpuSeconds"] - first[key]["cpuSeconds"]
                            for key in first if key[2] == role) / seconds
            for role in sorted(roles)
        }
        cpu = sum(by_role.values())
        summaries[phase] = {
            "seconds": seconds, "samples": len(window),
            "cpuPercentOneCore": cpu, "cpuPercentOneCoreByRole": by_role,
            "peakPrivateBytes": peak_private, "peakWorkingSetBytes": peak_working_set,
            "cpuWithinBudget": cpu <= cpu_limit,
        }
    return {"binarySha256": observations["binarySha256"], "phases": summaries}


if __name__ == "__main__":
    output = Path(sys.argv[1])
    log = (output / "fixture.log").read_text(encoding="utf-8-sig")
    data = json.loads((output / "process-samples.json").read_text(encoding="utf-8-sig"))
    result = summarize(log, data)
    (output / "desktop-summary.json").write_text(json.dumps(result, indent=2) + "\\n")
    print(json.dumps(result))
