import argparse
import json
import re
from pathlib import Path


def summarize(directory, minimum_seconds, settle_seconds):
    log = (directory / "fixture.log").read_text()
    markers = {}
    for phase, boundary, value in re.findall(
        r"^MEASURE (foreground|minimized) (start|end) (\\d+\\.\\d+)$", log, re.M
    ):
        if (phase, boundary) in markers:
            raise ValueError(f"duplicate {phase} {boundary} marker")
        markers[phase, boundary] = float(value)
    samples = [
        json.loads(line) for line in (directory / "process-samples.jsonl").read_text().splitlines()
    ]
    summary = {}
    for phase, cpu_budget in (("foreground", 1.0), ("minimized", 0.25)):
        begin, end = (markers[phase, key] for key in ("start", "end"))
        eligible = [row for row in samples if begin + settle_seconds <= row["at"] < end]
        if len(eligible) < 2:
            raise ValueError(f"missing samples in {phase}")
        seconds = eligible[-1]["at"] - eligible[0]["at"]
        if seconds < minimum_seconds:
            raise ValueError(f"short measurement window in {phase}: {seconds:.2f}s")
        count = len(eligible)
        peak_pss = 0
        start = previous = {}
        for index, sample in enumerate(eligible):
            members = {
                (p["pid"], p["started"], p["name"]): p for p in sample["members"]
            }
            if not any(key[0] == sample["host"] for key in members) or not any(
                key[2].startswith("WebKitWeb") for key in members
            ):
                raise ValueError(f"missing host or WebKit renderer in {phase}")
            if index == 0:
                start = members
            elif previous.keys() != members.keys() or any(
                current[counter] < previous[key][counter]
                for key, current in members.items()
                for counter in ("cpuSeconds", "writeBytes")
            ):
                raise ValueError(f"process family or counter changed in {phase}")
            previous = members
            peak_pss = max(peak_pss, sum(p["pssKiB"] for p in members.values()))
        cpu = 100 * sum(previous[key]["cpuSeconds"] - p["cpuSeconds"] for key, p in start.items()) / seconds
        writes = sum(previous[key]["writeBytes"] - p["writeBytes"] for key, p in start.items())
        summary[phase] = {
            "seconds": seconds,
            "samples": count,
            "cpuPercentOneCore": cpu,
            "cpuWithinBudget": cpu <= cpu_budget if seconds >= 300 else None,
            "peakPssKiB": peak_pss,
            "processWriteBytes": writes,
            "fullHourWriteBudgetObserved": (writes <= 5 * 1024**2) if seconds >= 3600 else None,
        }
    return {
        "binarySha256": (directory / "binary-sha256").read_text().split()[0],
        "phases": summary,
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", type=Path)
    parser.add_argument("--minimum-seconds", type=int, default=300)
    parser.add_argument("--settle-seconds", type=int, default=15)
    args = parser.parse_args()
    report = summarize(args.directory, args.minimum_seconds, args.settle_seconds)
    (args.directory / "desktop-summary.json").write_text(json.dumps(report, indent=2) + "\\n")
