text(await tools.exec_command({cmd:`cat > tmp/foundation-history-helper/src/bin/foundation-restore-density.rs <<'RS'
use mesh_talk_core::{
    eventlog::ConversationId,
    node::Node,
    recovery::{archive, key::RecoveryKey, snapshot::{read_snapshot, SnapshotRecordV1, SnapshotWriter}},
};
use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::{
    fs::{self, File, OpenOptions},
    io::{Seek, SeekFrom},
    path::Path,
    time::{SystemTime, UNIX_EPOCH},
};

#[derive(Deserialize)]
struct Manifest {
    completed: bool,
    accounts: Vec<String>,
    groups: Vec<[u8; 32]>,
    dm_per_contact: usize,
    group_messages: usize,
}

fn conversation(owner: &str, peer: &str) -> [u8; 32] {
    let (first, second) = if owner <= peer { (owner, peer) } else { (peer, owner) };
    let mut hash = Sha256::new();
    hash.update(b"mesh-talk-account-conversation-v1");
    hash.update((first.len() as u32).to_be_bytes());
    hash.update(first.as_bytes());
    hash.update(second.as_bytes());
    hash.finalize().into()
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    let [fixture, password_file, output, extra] = args.as_slice() else {
        return Err("expected fixture path, password file, output directory and new row count".into());
    };
    let fixture = Path::new(fixture);
    let output = Path::new(output);
    let extra: usize = extra.parse()?;
    let password = fs::read_to_string(password_file)?;
    let password = password.trim();
    let manifest: Manifest = serde_json::from_reader(File::open(fixture.join("manifest.json"))?)?;
    assert!(manifest.completed && !manifest.accounts.is_empty() && extra <= 100_000);
    let key = RecoveryKey::generate();
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis() as u64;
    let seed_path = output.join("seed.mtbackup");
    let seed = OpenOptions::new().write(true).create_new(true).open(&seed_path)?;
    let owner = Node::open_recovery_profile(&fixture.join("owner"), password)?;
    let owner_id = owner.account_id();
    owner.write_encrypted_recovery_archive(seed, &key, now)?;
    owner.close_profile()?;

    let scratch = output.join("scratch");
    fs::create_dir(&scratch)?;
    let mut decoded = tempfile::tempfile_in(&scratch)?;
    archive::read_archive(File::open(seed_path)?, &mut decoded, key.as_bytes())?;
    decoded.seek(SeekFrom::Start(0))?;
    let mut header = read_snapshot(&mut decoded, |_| Ok(()))?;
    assert_eq!(header.account_id, owner_id);
    header.record_count += extra as u64;
    decoded.seek(SeekFrom::Start(0))?;

    let expanded = output.join("expanded.mtbackup");
    let file = OpenOptions::new().write(true).create_new(true).open(&expanded)?;
    let mut encrypted = archive::ArchiveWriter::new(file, key.as_bytes())?;
    let mut writer = SnapshotWriter::new(&mut encrypted, &header)?;
    read_snapshot(decoded, |record| writer.push(&record))?;
    for (peer_index, peer) in manifest.accounts.iter().enumerate() {
        let conversation = conversation(&owner_id, peer);
        for row in (peer_index..extra).step_by(manifest.accounts.len()) {
            let mut hash = Sha256::new();
            hash.update(b"MeshTalkResourceEvalRecoveredMessageV1");
            hash.update(conversation);
            hash.update((row as u64).to_be_bytes());
            writer.push(&SnapshotRecordV1::SentDm {
                conversation,
                message_id: hash.finalize().into(),
                seq: row as u64 + 1,
                wall_clock: now.saturating_sub(extra as u64 - row as u64),
                plaintext: format!("Resource fixture direct message {row:06}").into_bytes(),
            })?;
        }
    }
    writer.finish()?;
    encrypted.finish()?;
    let (restored, preview) = Node::install_encrypted_recovery_archive(
        File::open(expanded)?, &key, &scratch, &output.join("restored"), password,
    )?;
    let mut observed = 0;
    for (index, peer) in manifest.accounts.iter().enumerate() {
        let count = manifest.dm_per_contact + (index..extra).step_by(manifest.accounts.len()).count();
        let rows = restored.account_history(peer, count + 1)?;
        assert_eq!(rows.len(), count);
        observed += rows.len();
    }
    for group in &manifest.groups {
        let rows = restored.channel_history(ConversationId::new(*group), manifest.group_messages + 1)?;
        assert_eq!(rows.len(), manifest.group_messages);
        observed += rows.len();
    }
    restored.close_profile()?;
    let total = extra + manifest.accounts.len() * manifest.dm_per_contact + manifest.groups.len() * manifest.group_messages;
    assert_eq!(observed, total);
    println!("{}", serde_json::json!({"restoredMessages":observed, "archiveMessages":preview.messages,"contacts":manifest.accounts.len(),"groups":manifest.groups.len()}));
    Ok(())
}
