use std::{hint::black_box, num::NonZeroU32, time::Instant};

fn main() {
    let rounds = NonZeroU32::new(600_000).unwrap();
    let providers: [(&str, fn(NonZeroU32, &[u8], &[u8], &mut [u8])); 3] = [
        ("rustcrypto", |n, password, salt, out| pbkdf2::pbkdf2_hmac::<sha2::Sha256>(password, salt, n.get(), out)),
        ("ring", |n, password, salt, out| ring::pbkdf2::derive(ring::pbkdf2::PBKDF2_HMAC_SHA256, n, salt, password, out)),
        ("aws-lc", |n, password, salt, out| aws_lc_rs::pbkdf2::derive(aws_lc_rs::pbkdf2::PBKDF2_HMAC_SHA256, n, salt, password, out)),
    ];
    for run in 0..12 {
        let password = [run as u8; 32];
        let salt = [0xA5 ^ (run as u8); 16];
        let mut values = [[0; 32]; 3];
        for rotation in 0..providers.len() {
            let index = (run + rotation) % providers.len();
            let (name, derive) = providers[index];
            let start = Instant::now();
            derive(rounds, black_box(&password), black_box(&salt), &mut values[index]);
