using System;
using System.Runtime.InteropServices;
public static class Req011ThreadNames {
  [DllImport("kernel32.dll", SetLastError=true)]
  static extern IntPtr OpenThread(uint access, bool inherit, uint id);
  [DllImport("kernel32.dll")]
  static extern int GetThreadDescription(IntPtr thread, out IntPtr description);
  [DllImport("kernel32.dll")]
  static extern IntPtr LocalFree(IntPtr memory);
  [DllImport("kernel32.dll")]
  static extern bool CloseHandle(IntPtr handle);
  public static string Name(uint id) {
    IntPtr thread = OpenThread(0x800, false, id);
    if (thread == IntPtr.Zero) return "";
    try {
      IntPtr result;
      if (GetThreadDescription(thread, out result) != 0 || result == IntPtr.Zero) return "";
      try { return Marshal.PtrToStringUni(result) ?? ""; }
      finally { LocalFree(result); }
    } finally { CloseHandle(thread); }
  }
}
'@
$instances = @(Get-Process -Name req011-driverless-loaded -ErrorAction SilentlyContinue | Where-Object { $_.Path -eq $ExpectedBinary })
if ($instances.Count -ne 1) { throw 'Expected one isolated host process' }
