  $rows = @{}
  foreach ($thread in $instance.Threads) {
    try {
      $rows[[int]$thread.Id] = @{ elapsed = $thread.TotalProcessorTime.TotalSeconds; name = [Req011ThreadNames]::Name([uint32]$thread.Id) }
    } catch [System.ComponentModel.Win32Exception] { }
  }
  return $rows
}
$clock = [Diagnostics.Stopwatch]::StartNew()
$begin = Snapshot $process.Id
Start-Sleep -Seconds $Seconds
$end = Snapshot $process.Id
$wall = $clock.Elapsed.TotalSeconds
$changes = @(
  foreach ($threadId in $end.Keys) {
    if ($begin.ContainsKey($threadId) -and $begin[$threadId].name -eq $end[$threadId].name) {
      $cpu = ($end[$threadId].elapsed - $begin[$threadId].elapsed) * 100 / $wall
      if ($cpu -gt 0) { @{ id = $threadId; name = $end[$threadId].name; cpuPercentOneCore = $cpu } }
    }
  }
)
@{ processId = $process.Id; elapsedSeconds = $wall; threads = @($changes | Sort-Object { $_.cpuPercentOneCore } -Descending) } | ConvertTo-Json -Depth 4
